"use client";

import { useEffect, useMemo, useState, useCallback } from "react";
import { useRef } from "react";
import { useAuth } from "@/hooks/use-auth";
import { useDashboardLayout } from "@/hooks/use-dashboard-layout";
import { DraggableWidget } from "@/components/DraggableWidget";
import { StyleCustomizer } from "@/components/StyleCustomizer";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend,
} from "recharts";
import { cn } from "@/lib/utils";
import { Edit3, Save, RotateCcw, Eye } from "lucide-react";
import { DEFAULT_DASHBOARD_STYLE } from "@/types/dashboard";

const MONTH_NAMES = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

export default function AnalyticsPage() {
  const { user } = useAuth();
  const userId = user?.id?.toString() || user?._id?.toString();

  const {
    widgets,
    styles,
    loading: layoutLoading,
    saving,
    editMode,
    setEditMode,
    updateWidgetPosition,
    toggleWidgetVisibility,
    removeWidget,
    updateStyles,
    resetLayout,
    saveLayout,
  } = useDashboardLayout(userId);

  const [projects, setProjects] = useState<any[]>([]);
  const [invoices, setInvoices] = useState<any[]>([]);
  const [clients, setClients] = useState<any[]>([]);
  const [team, setTeam] = useState<any[]>([]);
  const [servicesList, setServicesList] = useState<any[]>([]);
  const [expenses, setExpenses] = useState<any[]>([]);
  const [draggedWidget, setDraggedWidget] = useState<string | null>(null);
  const [dropTarget, setDropTarget] = useState<string | null>(null);

  useEffect(() => {
    let mounted = true;
    (async () => {
      try {
        const [pRes, iRes, cRes, tRes, sRes, eRes] = await Promise.all([
          fetch("/api/projects"),
          fetch("/api/invoices"),
          fetch("/api/clients"),
          fetch("/api/team-members"),
          fetch("/api/services"),
          fetch("/api/expenses"),
        ]);
        const [pJson, iJson, cJson, tJson, sJson, eJson] = await Promise.all([
          pRes.json(),
          iRes.json(),
          cRes.json(),
          tRes.json(),
          sRes.json(),
          eRes.json(),
        ]);
        if (!mounted) return;
        setProjects(pJson || []);
        setInvoices(iJson || []);
        setClients(cJson || []);
        setTeam(tJson || []);
        setServicesList(sJson || []);
        setExpenses(eJson || []);
      } catch (e) {
        console.error("Failed to load analytics data", e);
      }
    })();
    return () => {
      mounted = false;
    };
  }, []);

  // Analytics calculations
  const totalProjects = projects.length;
  const totalInvoices = invoices.length;
  const totalRevenue = invoices.reduce(
    (s, inv) => s + Number(inv.amount || 0),
    0,
  );
  const collected = invoices.reduce((s, inv) => {
    const paid =
      Number(inv.paidAmount ?? (inv.status === "PAID" ? inv.amount : 0)) || 0;
    return s + paid;
  }, 0);
  const pending = Math.max(0, totalRevenue - collected);

  const totalExpenses = expenses.reduce(
    (s, ex) => s + Number(ex.amount || 0),
    0,
  );

  const staffCount = team.length;
  const serviceCategories = servicesList.length;
  const assignedCount = projects.reduce(
    (s, p) => s + ((p.assignees || []).length || 0),
    0,
  );

  const devEditorEarnings = useMemo(() => {
    const earnings: { developers: number; editors: number } = {
      developers: 0,
      editors: 0,
    };
    const byId: Record<string, any> = {};
    for (const member of team || [])
      byId[String(member._id ?? member.id)] = member;
    for (const p of projects || []) {
      for (const a of p.assignees || []) {
        const member = byId[String(a.id)];
        const payout = Number(a.payout || 0);
        if (!member) continue;
        const role = (member.role || "").toLowerCase();
        if (role.includes("developer")) earnings.developers += payout;
        if (role.includes("editor")) earnings.editors += payout;
      }
    }
    return earnings;
  }, [projects, team]);

  const monthlyRevenue = useMemo(() => {
    const now = new Date();
    const months: { month: string; revenue: number; collected: number }[] = [];
    for (let i = 11; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      months.push({
        month: `${MONTH_NAMES[d.getMonth()]} ${d
          .getFullYear()
          .toString()
          .slice(-2)}`,
        revenue: 0,
        collected: 0,
      });
    }
    for (const inv of invoices || []) {
      const created = inv.createdAt
        ? new Date(inv.createdAt)
        : inv.dueDate
          ? new Date(inv.dueDate)
          : null;
      if (!created || Number.isNaN(created.getTime())) continue;
      const monthsAgo =
        (now.getFullYear() - created.getFullYear()) * 12 +
        (now.getMonth() - created.getMonth());
      if (monthsAgo >= 0 && monthsAgo < 12) {
        const idx = 11 - monthsAgo;
        months[idx].revenue += Number(inv.amount || 0);
        const paid =
          Number(inv.paidAmount ?? (inv.status === "PAID" ? inv.amount : 0)) ||
          0;
        months[idx].collected += paid;
      }
    }
    return months;
  }, [invoices]);

  const monthlyExpenses = useMemo(() => {
    const now = new Date();
    const months: { month: string; expense: number }[] = [];
    for (let i = 11; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      months.push({
        month: `${MONTH_NAMES[d.getMonth()]} ${d.getFullYear().toString().slice(-2)}`,
        expense: 0,
      });
    }
    for (const ex of expenses || []) {
      const created = ex.createdAt ? new Date(ex.createdAt) : null;
      if (!created || Number.isNaN(created.getTime())) continue;
      const monthsAgo =
        (now.getFullYear() - created.getFullYear()) * 12 +
        (now.getMonth() - created.getMonth());
      if (monthsAgo >= 0 && monthsAgo < 12) {
        const idx = 11 - monthsAgo;
        months[idx].expense += Number(ex.amount || 0);
      }
    }
    return months;
  }, [expenses]);

  const projectsByStatus = useMemo(() => {
    const acc: Record<string, number> = {};
    for (const p of projects || []) {
      const s = (p.status || "BACKLOG").toUpperCase();
      acc[s] = (acc[s] || 0) + 1;
    }
    return Object.entries(acc).map(([status, count]) => ({ status, count }));
  }, [projects]);

  const topClients = useMemo(() => {
    const map: Record<string, number> = {};
    for (const inv of invoices || []) {
      const id = inv.clientId ?? inv.client ?? inv.clientName ?? "Unknown";
      map[id] = (map[id] || 0) + Number(inv.amount || 0);
    }
    const rows = Object.entries(map).map(([id, amt]) => ({
      id,
      amt,
      name:
        clients.find((c) => String(c._id ?? c.id) === String(id))?.name || id,
    }));
    return rows.sort((a, b) => b.amt - a.amt).slice(0, 10);
  }, [invoices, clients]);

  const recentPayments = useMemo(() => {
    return (invoices || [])
      .slice()
      .sort(
        (a, b) =>
          new Date(b.createdAt || 0).getTime() -
          new Date(a.createdAt || 0).getTime(),
      )
      .slice(0, 8);
  }, [invoices]);

  const earningsByStaff = useMemo(() => {
    const byId: Record<string, any> = {};
    for (const m of team || []) {
      const id = String(m._id ?? m.id);
      byId[id] = {
        id,
        name: m.name || id,
        role: m.role || "",
        total: 0,
        clients: {} as Record<string, number>,
      };
    }

    const getClientName = (proj: any) => {
      const cid = proj.clientId ?? proj.client ?? proj.clientName ?? "";
      return (
        clients.find((c) => String(c._id ?? c.id) === String(cid))?.name ||
        proj.clientName ||
        proj.client ||
        "Unknown"
      );
    };

    for (const p of projects || []) {
      const clientName = getClientName(p);
      for (const a of p.assignees || []) {
        const mid = String(a.id ?? "unknown");
        const payout = Number(a.payout || 0);
        if (!byId[mid]) {
          byId[mid] = {
            id: mid,
            name: String(mid),
            role: "",
            total: 0,
            clients: {} as Record<string, number>,
          };
        }
        byId[mid].total += payout;
        byId[mid].clients[clientName] =
          (byId[mid].clients[clientName] || 0) + payout;
      }
    }

    return Object.values(byId).sort((a, b) => b.total - a.total);
  }, [projects, team, clients]);

  const colors = [
    "#8884d8",
    "#82ca9d",
    "#ffc658",
    "#ff7f50",
    "#a0d3ff",
    "#d0a0ff",
  ];

  // Count-up animation hook
  const useCountUp = (value: number, duration = 800) => {
    const ref = useRef<number>(0);
    const [display, setDisplay] = useState<number>(0);
    useEffect(() => {
      let start: number | null = null;
      const from = 0;
      const to = Number(value || 0);
      if (to === from) {
        setDisplay(to);
        return;
      }
      const step = (ts: number) => {
        if (!start) start = ts;
        const elapsed = Math.min(duration, ts - start);
        const pct = elapsed / duration;
        const cur = Math.round(from + (to - from) * pct);
        setDisplay(cur);
        if (elapsed < duration) {
          ref.current = requestAnimationFrame(step);
        }
      };
      ref.current = requestAnimationFrame(step);
      return () => {
        if (ref.current) cancelAnimationFrame(ref.current as any);
      };
    }, [value, duration]);
    return display;
  };

  const animatedTotalProjects = useCountUp(totalProjects, 900);
  const animatedTotalInvoices = useCountUp(totalInvoices, 900);
  const animatedTotalRevenue = useCountUp(totalRevenue, 1000);
  const animatedCollected = useCountUp(collected, 1000);
  const animatedPending = useCountUp(pending, 1000);
  const animatedTotalExpenses = useCountUp(totalExpenses, 1000);

  // Drag and drop handlers
  const handleDragStart = useCallback((widgetId: string) => {
    setDraggedWidget(widgetId);
  }, []);

  const handleDragOver = useCallback((e: React.DragEvent, widgetId: string) => {
    e.preventDefault();
    setDropTarget(widgetId);
  }, []);

  const handleDrop = useCallback(
    (e: React.DragEvent, targetWidgetId: string) => {
      e.preventDefault();
      if (!draggedWidget || draggedWidget === targetWidgetId) {
        setDraggedWidget(null);
        setDropTarget(null);
        return;
      }

      // Swap positions
      const draggedIndex = widgets.findIndex((w) => w.id === draggedWidget);
      const targetIndex = widgets.findIndex((w) => w.id === targetWidgetId);

      if (draggedIndex !== -1 && targetIndex !== -1) {
        const draggedPos = widgets[draggedIndex].position;
        const targetPos = widgets[targetIndex].position;

        updateWidgetPosition(draggedWidget, targetPos.x, targetPos.y);
        updateWidgetPosition(targetWidgetId, draggedPos.x, draggedPos.y);
      }

      setDraggedWidget(null);
      setDropTarget(null);
    },
    [draggedWidget, widgets, updateWidgetPosition],
  );

  const handleDragEnd = useCallback(() => {
    setDraggedWidget(null);
    setDropTarget(null);
  }, []);

  // Widget renderer
  const renderWidget = (widgetId: string) => {
    const widget = widgets.find((w) => w.id === widgetId);
    if (!widget || !widget.visible) return null;

    const commonProps = {
      id: widget.id,
      title: widget.title,
      editMode,
      onHide: () => toggleWidgetVisibility(widget.id),
      onRemove: () => removeWidget(widget.id),
      onRefresh: () => window.location.reload(),
      onDragStart: (e: React.DragEvent) => handleDragStart(widget.id),
      onDragEnd: handleDragEnd,
      styles,
    };

    switch (widgetId) {
      case "staff-count":
        return (
          <DraggableWidget {...commonProps} description="Total team members">
            <div className="text-4xl font-black">{staffCount}</div>
          </DraggableWidget>
        );

      case "service-categories":
        return (
          <DraggableWidget
            {...commonProps}
            description="Distinct services offered"
          >
            <div className="text-4xl font-black">{serviceCategories}</div>
          </DraggableWidget>
        );

      case "assigned-roles":
        return (
          <DraggableWidget
            {...commonProps}
            description="Total assignees across projects"
          >
            <div className="text-4xl font-black">{assignedCount}</div>
          </DraggableWidget>
        );

      case "dev-editor-earnings":
        return (
          <DraggableWidget
            {...commonProps}
            description="Sum of payouts to developers and editors"
          >
            <div className="text-sm">
              Developers: ₹
              {Number(devEditorEarnings.developers || 0).toLocaleString()}
            </div>
            <div className="text-sm">
              Editors: ₹
              {Number(devEditorEarnings.editors || 0).toLocaleString()}
            </div>
          </DraggableWidget>
        );

      case "total-projects":
        return (
          <DraggableWidget {...commonProps} description="Projects created">
            <div className="text-4xl font-black">{totalProjects}</div>
          </DraggableWidget>
        );

      case "total-invoices":
        return (
          <DraggableWidget {...commonProps} description="Invoices issued">
            <div className="text-4xl font-black">{totalInvoices}</div>
          </DraggableWidget>
        );

      case "revenue-generated":
        return (
          <DraggableWidget {...commonProps} description="Total of all invoices">
            <div className="text-4xl font-black">
              ₹{Number(animatedTotalRevenue || 0).toLocaleString()}
            </div>
          </DraggableWidget>
        );

      case "revenue-collected":
        return (
          <DraggableWidget
            {...commonProps}
            description="Sum of recorded payments (includes partials)"
          >
            <div className="text-4xl font-black">
              ₹{Number(animatedCollected || 0).toLocaleString()}
            </div>
          </DraggableWidget>
        );

      case "revenue-pending":
        return (
          <DraggableWidget
            {...commonProps}
            description="Remaining amount unpaid"
          >
            <div className="text-4xl font-black">
              ₹{Number(animatedPending || 0).toLocaleString()}
            </div>
          </DraggableWidget>
        );

      case "total-expenses":
        return (
          <DraggableWidget
            {...commonProps}
            description="Sum of recorded expenses"
          >
            <div className="text-4xl font-black">
              ₹{Number(animatedTotalExpenses || 0).toLocaleString()}
            </div>
          </DraggableWidget>
        );

      case "monthly-expenses-chart":
        return (
          <DraggableWidget
            {...commonProps}
            description="Shows expenses by month"
          >
            <div style={{ height: 280 }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={monthlyExpenses}
                  margin={{ top: 10, right: 20, left: 0, bottom: 5 }}
                >
                  <defs>
                    <linearGradient
                      id="gradExpense"
                      x1="0"
                      y1="0"
                      x2="0"
                      y2="1"
                    >
                      <stop offset="0%" stopColor="#f87171" stopOpacity={0.9} />
                      <stop
                        offset="100%"
                        stopColor="#fb7185"
                        stopOpacity={0.3}
                      />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
                  <XAxis dataKey="month" />
                  <YAxis tickFormatter={(v) => `₹${v / 1000}k`} />
                  <Tooltip
                    formatter={(v: any) => `₹${Number(v).toLocaleString()}`}
                  />
                  <Bar
                    dataKey="expense"
                    name="Expenses"
                    fill="url(#gradExpense)"
                    isAnimationActive
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </DraggableWidget>
        );

      case "expenses-table":
        return (
          <DraggableWidget
            {...commonProps}
            description="Recent expenses recorded in the system"
          >
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Title</TableHead>
                  <TableHead>Category</TableHead>
                  <TableHead className="text-right">Amount</TableHead>
                  <TableHead className="text-right">Date</TableHead>
                  <TableHead>Note</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {(expenses || []).slice(0, 5).map((ex) => (
                  <TableRow key={ex._id ?? ex.id}>
                    <TableCell className="font-bold">
                      {ex.title || "N/A"}
                    </TableCell>
                    <TableCell>{ex.category || "Uncategorized"}</TableCell>
                    <TableCell className="text-right">
                      ₹{Number(ex.amount || 0).toLocaleString()}
                    </TableCell>
                    <TableCell className="text-right">
                      {ex.createdAt
                        ? new Date(ex.createdAt).toLocaleDateString()
                        : "-"}
                    </TableCell>
                    <TableCell className="text-sm">{ex.note || "-"}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </DraggableWidget>
        );

      case "monthly-revenue-chart":
        return (
          <DraggableWidget
            {...commonProps}
            description="Shows total invoice amounts by month"
          >
            <div style={{ height: 320 }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={monthlyRevenue}
                  margin={{ top: 10, right: 20, left: 0, bottom: 5 }}
                >
                  <defs>
                    <linearGradient
                      id="gradCollected"
                      x1="0"
                      y1="0"
                      x2="0"
                      y2="1"
                    >
                      <stop
                        offset="0%"
                        stopColor="#34d399"
                        stopOpacity={0.95}
                      />
                      <stop
                        offset="100%"
                        stopColor="#10b981"
                        stopOpacity={0.3}
                      />
                    </linearGradient>
                    <linearGradient
                      id="gradRevenue"
                      x1="0"
                      y1="0"
                      x2="0"
                      y2="1"
                    >
                      <stop
                        offset="0%"
                        stopColor="#6366f1"
                        stopOpacity={0.95}
                      />
                      <stop
                        offset="100%"
                        stopColor="#4f46e5"
                        stopOpacity={0.3}
                      />
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
                  <XAxis dataKey="month" />
                  <YAxis tickFormatter={(v) => `₹${v / 1000}k`} />
                  <Tooltip
                    formatter={(v: any) => `₹${Number(v).toLocaleString()}`}
                  />
                  <Bar
                    dataKey="collected"
                    name="Collected"
                    fill="url(#gradCollected)"
                  />
                  <Bar
                    dataKey="revenue"
                    name="Generated"
                    fill="url(#gradRevenue)"
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </DraggableWidget>
        );

      case "projects-by-status":
        return (
          <DraggableWidget
            {...commonProps}
            description="Distribution of project statuses"
          >
            <div style={{ height: 320 }}>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={projectsByStatus}
                    dataKey="count"
                    nameKey="status"
                    innerRadius={40}
                    outerRadius={80}
                    label
                  >
                    {projectsByStatus.map((entry, idx) => (
                      <Cell
                        key={entry.status}
                        fill={colors[idx % colors.length]}
                      />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </DraggableWidget>
        );

      case "top-clients":
        return (
          <DraggableWidget
            {...commonProps}
            description="Clients who generated the most revenue"
          >
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Client</TableHead>
                  <TableHead className="text-right">Amount</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {topClients.map((c) => (
                  <TableRow key={c.id}>
                    <TableCell className="font-bold">{c.name}</TableCell>
                    <TableCell className="text-right">
                      ₹{Number(c.amt).toLocaleString()}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </DraggableWidget>
        );

      case "recent-payments":
        return (
          <DraggableWidget
            {...commonProps}
            description="Latest invoices created / updated"
          >
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Client</TableHead>
                  <TableHead className="text-right">Amount</TableHead>
                  <TableHead className="text-right">Status</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {recentPayments.map((inv) => (
                  <TableRow key={inv._id ?? inv.id}>
                    <TableCell>
                      {inv.clientName ||
                        inv.client ||
                        clients.find(
                          (c) => String(c._id ?? c.id) === String(inv.clientId),
                        )?.name ||
                        "-"}
                    </TableCell>
                    <TableCell className="text-right">
                      ₹{Number(inv.amount || 0).toLocaleString()}
                    </TableCell>
                    <TableCell
                      className={cn(
                        "text-right font-bold",
                        inv.status === "PAID"
                          ? "text-success"
                          : inv.status === "OVERDUE"
                            ? "text-destructive"
                            : "",
                      )}
                    >
                      {inv.status}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </DraggableWidget>
        );

      case "earnings-by-staff":
        return (
          <DraggableWidget
            {...commonProps}
            description="How much each team member earned and from which clients"
          >
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Name</TableHead>
                  <TableHead>Role</TableHead>
                  <TableHead className="text-right">Total Earned</TableHead>
                  <TableHead>Clients (top)</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {earningsByStaff.slice(0, 5).map((m: any) => (
                  <TableRow key={m.id}>
                    <TableCell className="font-bold">{m.name}</TableCell>
                    <TableCell>{m.role}</TableCell>
                    <TableCell className="text-right">
                      ₹{Number(m.total || 0).toLocaleString()}
                    </TableCell>
                    <TableCell>
                      {Object.entries(m.clients || {})
                        .sort((a, b) => (b[1] as number) - (a[1] as number))
                        .slice(0, 3)
                        .map(([cName, amt]) => (
                          <div key={cName} className="text-sm">
                            {cName}: ₹{Number(amt).toLocaleString()}
                          </div>
                        ))}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </DraggableWidget>
        );

      case "invoices-table":
        return (
          <DraggableWidget
            {...commonProps}
            description="All invoices with payment received and due amounts"
          >
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Invoice ID</TableHead>
                  <TableHead>Client</TableHead>
                  <TableHead className="text-right">Amount</TableHead>
                  <TableHead className="text-right">Payment Received</TableHead>
                  <TableHead className="text-right">Due Amount</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {invoices.slice(0, 5).map((inv) => {
                  const paid =
                    Number(
                      inv.paidAmount ??
                        (inv.status === "PAID" ? inv.amount : 0),
                    ) || 0;
                  const due = Math.max(0, Number(inv.amount || 0) - paid);
                  return (
                    <TableRow key={inv._id ?? inv.id}>
                      <TableCell className="font-bold">
                        {inv.invoiceNo || inv.id || inv._id}
                      </TableCell>
                      <TableCell>
                        {inv.clientName ||
                          inv.client ||
                          clients.find(
                            (c) =>
                              String(c._id ?? c.id) === String(inv.clientId),
                          )?.name ||
                          "-"}
                      </TableCell>
                      <TableCell className="text-right">
                        ₹{Number(inv.amount || 0).toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right">
                        ₹{paid.toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right">
                        ₹{due.toLocaleString()}
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </DraggableWidget>
        );

      default:
        return null;
    }
  };

  // Sort widgets by position for grid layout
  const sortedWidgets = useMemo(() => {
    return [...widgets]
      .filter((w) => w.visible)
      .sort((a, b) => {
        if (a.position.y !== b.position.y) {
          return a.position.y - b.position.y;
        }
        return a.position.x - b.position.x;
      });
  }, [widgets]);

  if (layoutLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-lg">Loading dashboard...</div>
      </div>
    );
  }

  return (
    <div className="space-y-6 font-headline">
      {/* Header with controls */}
      <header className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-5xl font-black tracking-tighter">ANALYTICS</h1>
          <p className="text-muted-foreground text-lg">
            Comprehensive analytics for your CRM — projects, invoices, and
            payments.
          </p>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          {/* Edit Mode Toggle */}
          <div className="flex items-center gap-2 border rounded-lg px-3 py-2">
            <Switch
              id="edit-mode"
              checked={editMode}
              onCheckedChange={setEditMode}
            />
            <Label
              htmlFor="edit-mode"
              className="cursor-pointer flex items-center gap-2"
            >
              {editMode ? (
                <>
                  <Edit3 className="h-4 w-4" />
                  Edit Mode ON
                </>
              ) : (
                <>
                  <Eye className="h-4 w-4" />
                  View Mode
                </>
              )}
            </Label>
          </div>

          {/* Style Customizer (Admin Only) */}
          {user?.role === "admin" && (
            <StyleCustomizer
              styles={styles}
              onStylesChange={updateStyles}
              onReset={() => updateStyles(DEFAULT_DASHBOARD_STYLE)}
            />
          )}

          {/* Save Button */}
          <Button
            onClick={saveLayout}
            disabled={saving}
            size="sm"
            className="gap-2"
          >
            <Save className="h-4 w-4" />
            {saving ? "Saving..." : "Save Layout"}
          </Button>

          {/* Reset Button */}
          <Button
            onClick={resetLayout}
            variant="outline"
            size="sm"
            className="gap-2"
          >
            <RotateCcw className="h-4 w-4" />
            Reset
          </Button>
        </div>
      </header>

      {/* Dashboard Grid */}
      <div
        className="relative"
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: styles.spacing || "1rem",
          gridAutoRows: "minmax(150px, auto)",
        }}
      >
        {sortedWidgets.map((widget) => (
          <div
            key={widget.id}
            onDragOver={(e) => handleDragOver(e, widget.id)}
            onDrop={(e) => handleDrop(e, widget.id)}
            className={cn(
              "transition-all duration-200",
              dropTarget === widget.id && "ring-2 ring-primary ring-offset-2",
            )}
            style={{
              gridColumn: `${widget.position.x + 1} / span ${widget.position.w}`,
              gridRow: `${widget.position.y + 1} / span ${widget.position.h}`,
            }}
          >
            {renderWidget(widget.id)}
          </div>
        ))}
      </div>

      {/* Empty state when all widgets are hidden */}
      {sortedWidgets.length === 0 && (
        <div className="text-center py-12 border-2 border-dashed rounded-lg">
          <p className="text-muted-foreground">
            All widgets are hidden. Click "Reset" to restore the default layout.
          </p>
        </div>
      )}
    </div>
  );
}
