"use client";

import { useState, useEffect, useCallback } from "react";
import {
  Widget,
  DashboardStyle,
  DEFAULT_WIDGETS,
  DEFAULT_DASHBOARD_STYLE,
} from "@/types/dashboard";

export function useDashboardLayout(userId: string | undefined) {
  const [widgets, setWidgets] = useState<Widget[]>(DEFAULT_WIDGETS);
  const [styles, setStyles] = useState<DashboardStyle>(DEFAULT_DASHBOARD_STYLE);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editMode, setEditMode] = useState(false);

  // Load dashboard layout from API
  const loadLayout = useCallback(async () => {
    if (!userId) {
      setLoading(false);
      return;
    }

    try {
      const response = await fetch(`/api/dashboard-layouts?userId=${userId}`);
      const data = await response.json();

      if (data && data.widgets) {
        setWidgets(data.widgets);
        setStyles(data.styles || DEFAULT_DASHBOARD_STYLE);
      } else {
        // Use defaults for first-time users
        setWidgets(DEFAULT_WIDGETS);
        setStyles(DEFAULT_DASHBOARD_STYLE);
      }
    } catch (error) {
      console.error("Failed to load dashboard layout:", error);
      setWidgets(DEFAULT_WIDGETS);
      setStyles(DEFAULT_DASHBOARD_STYLE);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  // Save dashboard layout to API
  const saveLayout = useCallback(async () => {
    if (!userId) return;

    setSaving(true);
    try {
      await fetch("/api/dashboard-layouts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId,
          widgets,
          styles,
        }),
      });
    } catch (error) {
      console.error("Failed to save dashboard layout:", error);
    } finally {
      setSaving(false);
    }
  }, [userId, widgets, styles]);

  // Reset dashboard to default
  const resetLayout = useCallback(async () => {
    if (!userId) return;

    try {
      await fetch(`/api/dashboard-layouts?userId=${userId}`, {
        method: "DELETE",
      });
      setWidgets(DEFAULT_WIDGETS);
      setStyles(DEFAULT_DASHBOARD_STYLE);
    } catch (error) {
      console.error("Failed to reset dashboard layout:", error);
    }
  }, [userId]);

  // Update widget position
  const updateWidgetPosition = useCallback(
    (widgetId: string, x: number, y: number) => {
      setWidgets((prev) =>
        prev.map((w) =>
          w.id === widgetId ? { ...w, position: { ...w.position, x, y } } : w,
        ),
      );
    },
    [],
  );

  // Update widget size
  const updateWidgetSize = useCallback(
    (widgetId: string, w: number, h: number) => {
      setWidgets((prev) =>
        prev.map((widget) =>
          widget.id === widgetId
            ? { ...widget, position: { ...widget.position, w, h } }
            : widget,
        ),
      );
    },
    [],
  );

  // Toggle widget visibility
  const toggleWidgetVisibility = useCallback((widgetId: string) => {
    setWidgets((prev) =>
      prev.map((w) => (w.id === widgetId ? { ...w, visible: !w.visible } : w)),
    );
  }, []);

  // Remove widget (hide it)
  const removeWidget = useCallback((widgetId: string) => {
    setWidgets((prev) =>
      prev.map((w) => (w.id === widgetId ? { ...w, visible: false } : w)),
    );
  }, []);

  // Update dashboard styles
  const updateStyles = useCallback((newStyles: Partial<DashboardStyle>) => {
    setStyles((prev) => ({ ...prev, ...newStyles }));
  }, []);

  // Load layout on mount
  useEffect(() => {
    loadLayout();
  }, [loadLayout]);

  // Auto-save when widgets or styles change (debounced)
  useEffect(() => {
    if (loading) return;

    const timer = setTimeout(() => {
      saveLayout();
    }, 1000); // Debounce for 1 second

    return () => clearTimeout(timer);
  }, [widgets, styles, loading, saveLayout]);

  return {
    widgets,
    styles,
    loading,
    saving,
    editMode,
    setEditMode,
    updateWidgetPosition,
    updateWidgetSize,
    toggleWidgetVisibility,
    removeWidget,
    updateStyles,
    resetLayout,
    saveLayout,
  };
}
