"use client";

import { ReactNode, useState, useRef, useEffect } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import {
  MoreVertical,
  Move,
  Maximize2,
  EyeOff,
  X,
  RefreshCw,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { DashboardStyle } from "@/types/dashboard";

interface DraggableWidgetProps {
  id: string;
  title: string;
  description?: string;
  children: ReactNode;
  editMode: boolean;
  onMove?: () => void;
  onResize?: () => void;
  onHide?: () => void;
  onRemove?: () => void;
  onRefresh?: () => void;
  onDragStart?: (e: React.DragEvent) => void;
  onDragEnd?: (e: React.DragEvent) => void;
  styles?: DashboardStyle;
  className?: string;
}

export function DraggableWidget({
  id,
  title,
  description,
  children,
  editMode,
  onMove,
  onResize,
  onHide,
  onRemove,
  onRefresh,
  onDragStart,
  onDragEnd,
  styles,
  className,
}: DraggableWidgetProps) {
  const [isDragging, setIsDragging] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);

  const handleDragStart = (e: React.DragEvent) => {
    setIsDragging(true);
    e.dataTransfer.effectAllowed = "move";
    e.dataTransfer.setData("text/plain", id);

    // Create a drag image
    if (cardRef.current) {
      const clone = cardRef.current.cloneNode(true) as HTMLElement;
      clone.style.opacity = "0.5";
      clone.style.position = "absolute";
      clone.style.top = "-9999px";
      document.body.appendChild(clone);
      e.dataTransfer.setDragImage(clone, 0, 0);
      setTimeout(() => document.body.removeChild(clone), 0);
    }

    onDragStart?.(e);
  };

  const handleDragEnd = (e: React.DragEvent) => {
    setIsDragging(false);
    onDragEnd?.(e);
  };

  const customStyles = styles
    ? {
        "--card-bg": styles.cardBackground,
        "--card-border-radius": styles.borderRadius,
        "--card-spacing": styles.spacing,
        "--card-font-size": styles.fontSize,
        "--card-accent": styles.accentColor,
        "--card-border-width": styles.borderWidth,
        "--card-border-color": styles.borderColor,
      }
    : {};

  return (
    <Card
      ref={cardRef}
      draggable={editMode}
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      className={cn(
        "relative transition-all duration-200 font-headline",
        editMode && "cursor-move hover:shadow-lg hover:scale-[1.02]",
        isDragging && "opacity-50 scale-95",
        className,
      )}
      style={
        {
          ...customStyles,
          backgroundColor: styles?.cardBackground,
          borderRadius: styles?.borderRadius,
          borderWidth: styles?.borderWidth,
          borderColor: styles?.borderColor,
          fontSize: styles?.fontSize,
        } as React.CSSProperties
      }
    >
      <CardHeader className="flex flex-row items-start justify-between space-y-0 pb-2">
        <div className="flex-1">
          <CardTitle className="text-lg font-bold">{title}</CardTitle>
          {description && (
            <CardDescription className="text-sm mt-1">
              {description}
            </CardDescription>
          )}
        </div>

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon" className="h-8 w-8 -mt-1 -mr-2">
              <MoreVertical className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-48">
            {editMode && (
              <>
                <DropdownMenuItem onClick={onMove}>
                  <Move className="mr-2 h-4 w-4" />
                  Move
                </DropdownMenuItem>
                <DropdownMenuItem onClick={onResize}>
                  <Maximize2 className="mr-2 h-4 w-4" />
                  Resize
                </DropdownMenuItem>
                <DropdownMenuSeparator />
              </>
            )}
            <DropdownMenuItem onClick={onHide}>
              <EyeOff className="mr-2 h-4 w-4" />
              Hide
            </DropdownMenuItem>
            <DropdownMenuItem onClick={onRemove} className="text-destructive">
              <X className="mr-2 h-4 w-4" />
              Remove
            </DropdownMenuItem>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={onRefresh}>
              <RefreshCw className="mr-2 h-4 w-4" />
              Refresh Data
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </CardHeader>

      <CardContent>{children}</CardContent>

      {editMode && (
        <div className="absolute inset-0 border-2 border-dashed border-primary/30 pointer-events-none rounded-lg" />
      )}
    </Card>
  );
}
